from typing import Any, List, Union, Optional, TypeVar, Callable, cast


T = TypeVar("T")


def from_list(f: Callable[[Any], T], x: Any) -> List[T]:
    assert isinstance(x, list)
    return [f(y) for y in x]


def from_none(x: Any) -> Any:
    assert x is None
    return x


def from_int(x: Any) -> int:
    assert isinstance(x, int) and not isinstance(x, bool)
    return x


def from_str(x: Any) -> str:
    assert isinstance(x, str)
    return x


def from_union(fs, x):
    for f in fs:
        try:
            return f(x)
        except:
            pass
    assert False


def is_type(t, x: Any) -> T:
    assert isinstance(x, t)
    return x


def to_class(c, x: Any) -> dict:
    assert isinstance(x, c)
    return cast(Any, x).to_dict()


class MixedClass:
    pass

    def __init__(self, ) -> None:
        pass

    @staticmethod
    def from_dict(obj: Any) -> 'MixedClass':
        assert isinstance(obj, dict)
        return MixedClass()

    def to_dict(self) -> dict:
        result: dict = {}
        return result


class MixedValues:
    mixed: List[Optional[Union[int, MixedClass]]]

    def __init__(self, mixed: List[Optional[Union[int, MixedClass]]]) -> None:
        self.mixed = mixed

    @staticmethod
    def from_dict(obj: Any) -> 'MixedValues':
        assert isinstance(obj, dict)
        mixed = from_list(lambda x: from_union([from_none, from_int, lambda x: int(from_str(x)), MixedClass.from_dict], x), obj["mixed"])
        return MixedValues(mixed)

    def to_dict(self) -> dict:
        result: dict = {}
        result["mixed"] = from_list(lambda x: from_union([lambda x: from_none((lambda x: is_type(type(None), x))(x)), lambda x: from_int((lambda x: is_type(int, x))(x)), lambda x: to_class(MixedClass, (lambda x: is_type(MixedClass, x))(x))], x), self.mixed)
        return result


def mixed_values_from_dict(s: Any) -> MixedValues:
    return MixedValues.from_dict(s)


def mixed_values_to_dict(x: MixedValues) -> Any:
    return to_class(MixedValues, x)

